/* Standalone design prototype. Every address and figure below is synthetic. */
const profiles = [
  { id:'trader', name:'Active trader', address:'0x1111111111111111111111111111111111111111', description:'Frequent verified swaps across several trading days.', period:30, count:68, balance:186420, risk:46, action:'Swaps on 19 days', protocols:['Uniswap','No protocol'], assets:[['ETH',24.18,59250],['USDC',78200,78200],['WETH',20,48970]], score:90 },
  { id:'holder', name:'Long-term holder', address:'0x2222222222222222222222222222222222222222', description:'Balances retained with limited recent outgoing activity.', period:180, count:10, balance:412650, risk:18, action:'90-day retention', protocols:['No protocol'], assets:[['ETH',140,341600],['USDC',71050,71050]], score:100 },
  { id:'defi', name:'DeFi participant', address:'0x3333333333333333333333333333333333333333', description:'Repeated lending, borrowing and liquidity actions.', period:90, count:48, balance:97280, risk:39, action:'Lending and liquidity', protocols:['Aave','Uniswap'], assets:[['ETH',13,31720],['USDC',45600,45600],['aUSDC',19960,19960]], score:80 },
  { id:'nft', name:'NFT trader', address:'0x4444444444444444444444444444444444444444', description:'Verified buys and sales across NFT marketplaces.', period:30, count:34, balance:32670, risk:55, action:'NFT purchases and sales', protocols:['OpenSea','Blur'], assets:[['ETH',9,21970],['WETH',4.38,10700]], score:70 },
  { id:'staking', name:'Staking participant', address:'0x5555555555555555555555555555555555555555', description:'Active staking position supported by deposit history.', period:180, count:19, balance:120450, risk:16, action:'Active stake', protocols:['Lido','No protocol'], assets:[['stETH',38,92720],['ETH',11.36,27730]], score:100 },
  { id:'dormant', name:'Dormant or new wallet', address:'0x6666666666666666666666666666666666666666', description:'No wallet-initiated transaction during the last 90 days.', period:180, count:2, balance:83110, risk:20, action:'No recent sends', protocols:['No protocol'], assets:[['ETH',32,78110],['USDC',5000,5000]], score:null },
];
const tabs = [
  ['overview','Overview'],['balances','Balances'],['activity','Activity'],
  ['movements','Token movements'],['flows','Fund flows'],
  ['protocols','Protocols used'],['risk','Risk indicators'],['evidence','Profile evidence'],
];
const state = { screen:'home', wallet:null, tab:'overview', period:90, input:'', error:'', loading:false, dialog:null, selectedProtocol:null, pages:{} };
const app = document.getElementById('app');
const money = value => '$' + Number(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const short = value => value.slice(0,6) + '…' + value.slice(-4);
const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function txRows(wallet, period){
  const actions = wallet.id==='trader' ? ['Swap','Swap','Transfer'] : wallet.id==='defi' ? ['Supply','Borrow','Repay','Swap'] : wallet.id==='nft' ? ['Buy NFT','Sell NFT','Transfer'] : wallet.id==='staking' ? ['Stake','Claim','Transfer'] : ['Transfer'];
  return Array.from({length:wallet.count},(_,i)=>{
    const activeSpan = {trader:19,holder:8,defi:25,nft:11,staking:8,dormant:2}[wallet.id] || 8;
    const age = wallet.id==='dormant' ? 4 + i*17 : wallet.id==='holder' ? 3 + (i%activeSpan)*18 : 1 + (i % Math.min(activeSpan,period-1));
    const action=actions[i%actions.length];
    const incoming=wallet.id==='dormant' || (wallet.id==='holder' && i%4!==0) || (wallet.id!=='holder' && i%4===0);
    const protocol=wallet.protocols[i%wallet.protocols.length];
    const value=wallet.id==='dormant' ? (i ? 0.07 : 0.58) : Math.round((40+(i*157)%2800)*100)/100;
    const counterparty='0x'+String('abcdef'[i%6]).repeat(40);
    return {hash:'0x'+BigInt(0x100000+i+wallet.count*1000).toString(16).padStart(64,'0'),age,action,protocol,incoming,value,counterparty,token:wallet.id==='nft'?'ETH':i%3===0?'USDC':'ETH'};
  }).sort((a,b)=>a.age-b.age);
}
const timeAgo = days => days===0?'19 min ago':days===1?'1 day ago':`${days} days ago`;
const card = (title,subtitle,body) => `<section class="panel"><div class="panel-header"><div><h3>${title}</h3><p>${subtitle}</p></div></div>${body}</section>`;
function header(){return `<header class="topbar"><div class="shell topbar-inner"><a href="#/home" class="brand" data-action="home"><span class="brand-mark">▣</span>OnChain</a><span class="prototype-tag">Interactive prototype · sample data</span><nav class="nav-links"><a href="#/home" data-action="home">Home</a><a href="#/profiler" class="button small" data-action="open-profiler">Open profiler ↗</a></nav></div></header>`}
function footer(){return `<footer class="footer"><span>▣ OnChain Wallet Profiler</span><span>Ethereum wallet analytics</span><span>Prototype · synthetic wallet data</span></footer>`}
function home(){return `${header()}<main><section class="shell hero"><div class="hero-copy"><span class="eyebrow">Ethereum wallet analytics</span><h1>Understand a wallet’s <em>behavior.</em></h1><p>Look beyond the transaction list. Explore how a wallet trades, the protocols it uses, and the evidence behind its behavioral profile.</p><div class="hero-actions"><button class="button primary" data-action="open-profiler">Explore the profiler →</button><button class="button ghost" data-action="sample" data-wallet="trader">View sample analysis</button></div><small class="hero-note">Click-through design prototype · no wallet connection required</small></div><div class="flow-card"><small>From onchain activity to insight</small><div class="flow-step"><span class="flow-icon">⌁</span><div><h3>Transaction activity</h3><p>Frequency, volume and active days</p></div></div><div class="flow-step"><span class="flow-icon">▱</span><div><h3>Protocols used</h3><p>Trading, lending and staking interactions</p></div></div><div class="flow-step"><span class="flow-icon">◷</span><div><h3>Timing patterns</h3><p>Consistency, bursts and changes over time</p></div></div><div class="flow-result"><span class="flow-icon">▣</span><div><strong>A behavioral profile</strong><p class="muted">Patterns connected. Evidence explained.</p></div></div></div></section><div class="capabilities"><div class="shell"><span>Behavioral profiles</span><span>Activity history</span><span>Protocol interactions</span><span>Explainable indicators</span></div></div><section class="shell home-profiles"><small class="label">01 / Wallet profiles</small><h2>Different activity. Different profiles.</h2><div class="profile-grid">${profiles.map(p=>`<button class="profile-tile" data-action="sample" data-wallet="${p.id}"><span class="label">↗ SAMPLE WALLET</span><strong>${p.name}</strong><p>${p.description}</p></button>`).join('')}</div>${footer()}</section></main>`}
function searchForm(){return `<form id="search-form" class="search-card"><span style="padding-left:13px;color:var(--muted)">⌕</span><input id="address-input" aria-label="Ethereum wallet address" autocomplete="off" spellcheck="false" placeholder="Enter an Ethereum wallet address (0x…)" value="${escapeHtml(state.input)}"/><select id="period-select" aria-label="Analysis period">${[30,90,180].map(n=>`<option value="${n}" ${state.period===n?'selected':''}>Last ${n} days</option>`).join('')}</select><button class="button primary" type="submit">Analyze wallet →</button></form>`}
function samples(){return `<details class="wallet-samples" ${state.wallet?'':'open'}><summary>Choose a sample wallet <span class="muted">· prototype scenarios</span></summary><div class="sample-list">${profiles.map(p=>`<button class="pill" data-action="sample" data-wallet="${p.id}" title="${p.address}">${p.name}</button>`).join('')}<button class="pill" data-action="contract-demo">Smart contract error</button></div><small style="margin-top:10px">These are synthetic addresses. Selecting one changes the entire dashboard.</small></details>`}
function empty(){return `<div class="empty"><span class="empty-icon">▣</span><h2>Enter a wallet address to start analysis</h2><p>Select a sample wallet above to explore the prototype. Free-form addresses do not call a live API.</p></div>`}
function loading(){return `<div class="loading" aria-busy="true"><span class="label"><span class="spinner"></span>Analyzing sample wallet</span><div class="skeleton short"></div><div class="skeleton wide"></div><div class="skeleton mid"></div><div class="skeleton"></div></div>`}
function metrics(wallet,txs){const active=new Set(txs.map(t=>t.age)).size;return `<div class="metric-row"><div class="metric"><small>Transactions</small><strong>${txs.length}</strong><span>Across the selected period</span></div><div class="metric"><small>Transfer volume</small><strong>${money(txs.reduce((sum,t)=>sum+t.value,0))}</strong><span>Illustrative gross flow</span></div><div class="metric"><small>Unique counterparties</small><strong>${new Set(txs.map(t=>t.counterparty)).size}</strong><span>Distinct addresses</span></div><div class="metric"><small>Active days</small><strong>${active} / ${state.period}</strong><span>${Math.round(active/state.period*100)}% activity rate</span></div></div>`}
function profileHero(wallet,txs){const active=new Set(txs.map(t=>t.age)).size;const identified=wallet.protocols.filter(p=>p!=='No protocol').length;return `<div class="profile-card"><div class="profile-main"><div><span class="label">Behavioral profile</span> <span class="muted">· ${state.period}-day analysis</span><h2>${wallet.name}</h2><p>${wallet.description}</p><div class="profile-chips"><span>${wallet.name}${wallet.score===null?'':` · ${wallet.score}/100`}</span><span>Illustrative evidence</span></div></div><div class="profile-aside"><small>Behavioral anomaly</small><strong>${wallet.risk}<small style="display:inline;font-size:12px"> /100</small></strong><div class="gauge"><i style="width:${wallet.risk}%"></i></div><small>${wallet.risk<30?'Typical pattern':wallet.risk<50?'Moderate deviation':'Higher deviation'} · sample score</small></div></div><div class="profile-stats"><div><small>Active days</small><strong>${active} of ${state.period}</strong><small>days</small></div><div><small>Protocols used</small><strong>${identified}</strong><small>named protocols</small></div><div><small>Transaction frequency</small><strong>${(txs.length/state.period).toFixed(1)}</strong><small>tx / day</small></div></div></div>`}
function pager(total){const page=state.pages[state.tab]||0;const pages=Math.max(1,Math.ceil(total/10));return `<div class="pager"><span>${total?`${page*10+1}–${Math.min((page+1)*10,total)} of ${total}`:'No records'}</span><div><button data-action="page" data-page="${page-1}" ${page===0?'disabled':''}>← Previous</button><span style="margin-left:10px">Page ${page+1} of ${pages}</span><button data-action="page" data-page="${page+1}" ${page+1>=pages?'disabled':''}>Next →</button></div></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="muted">No activity in this sample.</td></tr>`}</tbody></table></div>`}
function activity(wallet,txs){const list=state.selectedProtocol?txs.filter(t=>t.protocol===state.selectedProtocol):txs;const page=state.pages[state.tab]||0;return card('Transaction activity',`${list.length} sample activity records · last ${state.period} days${state.selectedProtocol?` · ${String(state.selectedProtocol)}`:''}`,`${state.selectedProtocol?'<button class="button small ghost" data-action="clear-protocol" style="margin-bottom:12px">Clear protocol filter ×</button>':''}${table(['Transaction','Action','Protocol','Direction','Value','Age'],list.slice(page*10,page*10+10).map(t=>`<tr><td><button class="link-button" data-action="transaction" data-hash="${t.hash}">${short(t.hash)}</button></td><td>${t.action}</td><td>${t.protocol}</td><td class="${t.incoming?'positive':'negative'}">${t.incoming?'Received':'Sent'}</td><td>${money(t.value)}</td><td title="${t.age} days before prototype snapshot">${timeAgo(t.age)}</td></tr>`))}${pager(list.length)}`)}
function balances(wallet){const rows=wallet.assets.map(([symbol,amount,value])=>`<tr><td><strong>${symbol}</strong><small>Ethereum asset</small></td><td>${Number(amount).toLocaleString()} ${symbol}</td><td>${money(value/amount)}</td><td><strong>${money(value)}</strong></td><td>${(value/wallet.balance*100).toFixed(1)}%</td></tr>`);return card('Assets on Ethereum','Illustrative balances at the snapshot date',`<div class="flows"><div><small>Total balance</small><strong>${money(wallet.balance)}</strong></div><div><small>Assets</small><strong>${wallet.assets.length}</strong></div><div><small>Network</small><strong>Ethereum</strong></div></div>${table(['Asset','Balance','Price','Value','Allocation'],rows)}`)}
function movements(txs){const page=state.pages[state.tab]||0;return card('Token movements','Incoming and outgoing asset movements on Ethereum',`${table(['Direction','Amount','Value','From','To','Protocol','Age'],txs.slice(page*10,page*10+10).map(t=>`<tr><td class="${t.incoming?'positive':'negative'}">${t.incoming?'↙ Received':'↗ Sent'}</td><td>${t.token==='ETH'?(t.value/2400).toFixed(5):t.value.toFixed(2)} ${t.token}</td><td>${money(t.value)}</td><td>${short(t.incoming?t.counterparty:state.wallet.address)}</td><td>${short(t.incoming?state.wallet.address:t.counterparty)}</td><td>${t.protocol}</td><td>${timeAgo(t.age)}</td></tr>`))}${pager(txs.length)}`)}
function fundFlows(txs){const incoming=txs.filter(t=>t.incoming).reduce((n,t)=>n+t.value,0);const outgoing=txs.filter(t=>!t.incoming).reduce((n,t)=>n+t.value,0);const groups=[...new Set(txs.map(t=>t.counterparty))].map(address=>{const items=txs.filter(t=>t.counterparty===address);return {address,in:items.filter(t=>t.incoming).reduce((n,t)=>n+t.value,0),out:items.filter(t=>!t.incoming).reduce((n,t)=>n+t.value,0)}});const page=state.pages[state.tab]||0;return card('Fund flows',`Asset movements · last ${state.period} days`,`<div class="flows"><div><small>Incoming</small><strong>${money(incoming)}</strong></div><div><small>Outgoing</small><strong>${money(outgoing)}</strong></div><div><small>Net flow</small><strong>${money(incoming-outgoing)}</strong></div></div><p class="muted" style="margin-bottom:15px">Counterparties are addresses; a contract can also be a counterparty. Sample amounts are not profit or loss.</p>${table(['Counterparty','Incoming','Outgoing','Total flow'],groups.slice(page*10,page*10+10).map(g=>`<tr><td><strong>${short(g.address)}</strong></td><td class="positive">${money(g.in)}</td><td class="negative">${money(g.out)}</td><td>${money(g.in+g.out)}</td></tr>`))}${pager(groups.length)}`)}
function protocols(wallet,txs){const groups=wallet.protocols.map(name=>({name,count:txs.filter(t=>t.protocol===name).length}));return card('Protocols used','Select a protocol to inspect its activity',`${groups.map(g=>`<div class="protocol-line"><button data-action="protocol" data-protocol="${g.name}"><strong>${g.name}</strong><small>${g.name==='No protocol'?'Direct wallet activity':'Attributed interaction'}</small></button><strong>${g.count} records ↗</strong></div>`).join('')}<p class="muted" style="margin-top:18px">Protocol labels identify applications; counterparties identify addresses.</p>`)}
function risk(wallet){return card('Behavioral risk indicators','Illustrative activity signals for discussion',`<div class="risk-number">${wallet.risk}<small style="font-size:14px">/100</small></div><div class="gauge"><i style="width:${wallet.risk}%"></i></div><div class="evidence-row"><div><strong>Activity concentration</strong><p>${wallet.action}</p></div><span class="status">Observed</span></div><div class="evidence-row"><div><strong>Protocol exposure</strong><p>${wallet.protocols.join(', ')}</p></div><span class="status">Illustrative</span></div><div class="notice">This prototype score is sample data. It is not a fraud, legal, credit or investment rating.</div>`)}
function evidence(wallet){return card('Profile rule results','Six independent decisions · illustrative evidence',`${profiles.map(p=>`<div class="evidence-row"><div><strong>${p.name}</strong><p>${p.id===wallet.id?wallet.description:'The sample wallet does not meet this profile’s example conditions.'}</p></div><span class="status">${p.id===wallet.id?(wallet.score===null?'Assigned':`${wallet.score}/100 · Assigned`):'Not assigned'}</span></div>`).join('')}<div class="notice">Rule scores show matched example criteria, not a measured confidence percentage.</div>`)}
function overview(wallet,txs){const active=new Set(txs.map(t=>t.age)).size;const bins=Array.from({length:24},(_,i)=>txs.filter(t=>Math.floor(t.age/(state.period/24))===i).length);const heat=Array.from({length:state.period},(_,i)=>txs.filter(t=>t.age===state.period-1-i).length);return `${metrics(wallet,txs)}<div class="overview-grid">${card('Transaction activity','Transactions per interval',`<div class="chart">${bins.map(n=>`<i style="height:${Math.min(95,Math.max(3,n*12))}%"></i>`).join('')}</div>`)}${card('Protocols used','Attributed activity in the selected period',wallet.protocols.map(name=>`<div class="protocol-line"><button data-action="protocol" data-protocol="${name}"><strong>${name}</strong></button><strong>${txs.filter(t=>t.protocol===name).length}</strong></div>`).join(''))}</div>${card('Activity heatmap',`${active} active days in the last ${state.period} days`,`<div class="heatmap">${heat.map(n=>`<i class="${n?`hot${Math.min(n,3)}`:''}" title="${n} record${n===1?'':'s'}"></i>`).join('')}</div>`)}`}
function mainPanel(wallet,txs){switch(state.tab){case 'balances':return balances(wallet);case 'activity':return activity(wallet,txs);case 'movements':return movements(txs);case 'flows':return fundFlows(txs);case 'protocols':return protocols(wallet,txs);case 'risk':return risk(wallet);case 'evidence':return evidence(wallet);default:return overview(wallet,txs)}}
function dashboard(wallet){const txs=txRows(wallet,state.period);return `<div class="identity"><div><div class="address-line"><span class="network">Ethereum</span><span class="address-text">${short(wallet.address)}</span><span class="prototype-tag">Synthetic address</span></div><p class="meta">Analysis period: Last ${state.period} days · sample snapshot</p></div><button class="button small ghost" disabled title="Export disabled in prototype">Export profile</button></div>${profileHero(wallet,txs)}<nav class="tabs" aria-label="Profiler sections">${tabs.map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" data-action="tab" data-tab="${id}">${label}</button>`).join('')}</nav>${mainPanel(wallet,txs)}`}
function profiler(){const wallet=state.wallet;return `${header()}<main class="shell page"><div class="page-title"><h1>Wallet profiler</h1><p>Understand a wallet through its behavior.</p></div>${searchForm()}${state.error?`<div class="notice error" role="alert">${escapeHtml(state.error)}</div>`:''}${samples()}${state.loading?loading():wallet?dashboard(wallet):empty()}${footer()}</main>${state.dialog?dialog():''}`}
function dialog(){const tx=state.dialog;return `<div class="overlay" data-action="close-dialog"><div class="dialog" role="dialog" aria-modal="true" aria-label="Transaction details"><div class="dialog-head"><h2>Transaction details</h2><button class="button small ghost" data-action="close-dialog">Close ×</button></div><small>Transaction hash</small><code>${tx.hash}</code><div class="evidence-row"><span>Action</span><strong>${tx.action}</strong></div><div class="evidence-row"><span>Protocol</span><strong>${tx.protocol}</strong></div><div class="evidence-row"><span>Direction</span><strong>${tx.incoming?'Received':'Sent'}</strong></div><div class="evidence-row"><span>Counterparty</span><code>${tx.counterparty}</code></div><div class="evidence-row"><span>Sample value</span><strong>${money(tx.value)}</strong></div><div class="evidence-row"><span>Age</span><strong>${timeAgo(tx.age)}</strong></div></div></div>`}
function render(){app.innerHTML=state.screen==='home'?home():profiler();document.title=`OnChain · ${state.screen==='home'?'Prototype':state.wallet?state.wallet.name:'Wallet profiler'}`}
function route(){if(state.screen==='home'){location.hash='/home';return}location.hash=`/profiler/${state.tab}${state.wallet?`?wallet=${state.wallet.id}&period=${state.period}`:state.error.startsWith('Smart contract')?'?error=contract':''}`}
function chooseWallet(id){const wallet=profiles.find(p=>p.id===id);if(!wallet)return;state.screen='profiler';state.wallet=null;state.input=wallet.address;state.period=wallet.period;state.error='';state.loading=true;state.tab='overview';state.pages={};state.selectedProtocol=null;window.scrollTo(0,0);render();window.setTimeout(()=>{state.wallet=wallet;state.loading=false;route();render()},550)}
function restore(){const raw=location.hash.slice(1)||'/home';if(!raw.startsWith('/profiler')){state.screen='home';state.wallet=null;render();return}const [path,query='']=raw.split('?');const id=path.split('/')[2];const params=new URLSearchParams(query);state.screen='profiler';state.tab=tabs.some(([key])=>key===id)?id:'overview';state.wallet=profiles.find(p=>p.id===params.get('wallet'))||null;state.period=[30,90,180].includes(Number(params.get('period')))?Number(params.get('period')):(state.wallet?.period||90);state.input=state.wallet?.address||'';state.error='';if(params.get('error')==='contract'){state.input='0x'+'9'.repeat(40);state.error='Smart contract detected. Behavioral wallet analysis is available only for externally owned accounts.'}state.loading=false;render()}
document.addEventListener('click',event=>{const hit=event.target.closest('[data-action]');if(!hit)return;const action=hit.dataset.action;if(action==='home'){event.preventDefault();state.screen='home';state.wallet=null;route();render();window.scrollTo(0,0)}else if(action==='open-profiler'){event.preventDefault();state.screen='profiler';state.wallet=null;state.input='';state.error='';state.loading=false;route();render();window.scrollTo(0,0)}else if(action==='sample'){chooseWallet(hit.dataset.wallet)}else if(action==='contract-demo'){state.screen='profiler';state.wallet=null;state.input='0x'+'9'.repeat(40);state.error='Smart contract detected. Behavioral wallet analysis is available only for externally owned accounts.';state.loading=false;route();render()}else if(action==='tab'){state.tab=hit.dataset.tab;state.selectedProtocol=null;route();render()}else if(action==='page'){state.pages[state.tab]=Number(hit.dataset.page);render()}else if(action==='transaction'){state.dialog=txRows(state.wallet,state.period).find(t=>t.hash===hit.dataset.hash);render()}else if(action==='close-dialog'){if(hit.classList.contains('overlay')&&event.target!==hit)return;state.dialog=null;render()}else if(action==='protocol'){state.tab='activity';state.selectedProtocol=hit.dataset.protocol;state.pages.activity=0;route();render()}else if(action==='clear-protocol'){state.selectedProtocol=null;render()}});
document.addEventListener('submit',event=>{if(event.target.id!=='search-form')return;event.preventDefault();const input=document.getElementById('address-input').value.trim();state.input=input;if(!/^0x[a-fA-F0-9]{40}$/.test(input)){state.error='Enter a valid Ethereum address: 0x followed by 40 hexadecimal characters.';render();return}if(input.toLowerCase()==='0x'+'9'.repeat(40)){state.wallet=null;state.error='Smart contract detected. Behavioral wallet analysis is available only for externally owned accounts.';render();return}const wallet=profiles.find(p=>p.address.toLowerCase()===input.toLowerCase());if(!wallet){state.wallet=null;state.error='This offline prototype contains only the six synthetic sample wallets shown above.';render();return}chooseWallet(wallet.id)});
document.addEventListener('change',event=>{if(event.target.id==='period-select'){state.period=Number(event.target.value);state.pages={};route();render()}});
document.addEventListener('input',event=>{if(event.target.id==='address-input')state.input=event.target.value});
window.addEventListener('hashchange',restore);restore();
